// Inlines the generated Durable Object migrations into a TypeScript module.
//
// drizzle-kit emits a `migrations.js` that `import`s the raw .sql files, which
// would force a text-module loader into both the wrangler build and vitest.
// Inlining sidesteps that entirely and keeps the migrations importable like any
// other module. Regenerated by `bun run db:generate`; do not edit by hand.
import { readdir, readFile, writeFile } from "node:fs/promises";
import path from "node:path";

const root = path.resolve(import.meta.dirname, "..");
const migrationsDir = path.join(root, "migrations", "do");
const target = path.join(root, "src", "do", "migrations.ts");

const entries = (await readdir(migrationsDir, { withFileTypes: true }))
  .filter((entry) => entry.isDirectory())
  .map((entry) => entry.name)
  .sort();

const parts = await Promise.all(
  entries.map(async (name) => {
    const sql = await readFile(path.join(migrationsDir, name, "migration.sql"), "utf8");
    return `  ${JSON.stringify(name)}: ${JSON.stringify(sql)},`;
  }),
);

await writeFile(
  target,
  `// GENERATED by scripts/bundle-do-migrations.mjs — do not edit.\n` +
    `// Run \`bun run db:generate\` in packages/db to refresh.\n\n` +
    `export const durableObjectMigrations: Record<string, string> = {\n${parts.join("\n")}\n};\n`,
);

console.log(`Bundled ${entries.length} Durable Object migration(s) into src/do/migrations.ts`);
